import fs from 'node:fs';
const protocol = JSON.parse(fs.readFileSync('protocol.json', 'utf8'));
const blocks = fs.readFileSync('runs/blocks.csv', 'utf8').trim().split('\n').slice(1).map(line => {
  const [block,n,violations,completed,rejected,timedOut,unfinished] = line.split(',').map(Number);
  return {block,n,violations,completed,rejected,timedOut,unfinished};
});
for (const row of blocks) console.log(JSON.stringify({type:'progress', ...row}));
const chosen = protocol.selector === 'fixed'
  ? blocks.find(row => row.block === protocol.primaryBlock)
  : blocks.find(row => row.violations === 0);
if (!chosen) throw new Error('No block qualifies for publication');
const result = {...chosen, upper95: chosen.violations === 0 ? -Math.expm1(Math.log(0.05)/chosen.n) : null};
fs.writeFileSync('runs/published.json', JSON.stringify(result, null, 2));
